template.query:
query OptimizeQueries($options: OptimizationOptions) {
  queryOptimization(options: $options) {
    analysis {
      slowQueries {
        query
        avgExecutionTime
        executionCount
        lastExecuted
        optimization {
          currentPlan
          suggestedPlan
          expectedImprovement
        }
      }
      indexRecommendations {
        table
        columns
        type
        estimatedImprovement
        creationCost
        maintenanceCost
      }
      performanceBottlenecks {
        type
        description
        severity
        impact
        solution
      }
    }
    recommendations {
      immediate {
        action
        description
        expectedGain
        effort
      }
      longTerm {
        action
        description
        expectedGain
        effort
      }
    }
    metrics {
      currentPerformance {
        avgQueryTime
        queriesPerSecond
        cacheHitRate
      }
      projectedPerformance {
        avgQueryTime
        queriesPerSecond
        cacheHitRate
      }
    }
  }
}
